import{_ as t,o,c as a,a5 as n}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"FR 3.9.2 — Make Payment (SePay)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/08-subscription-billing/3-9-2-make-payment-sepay/spec.md","filePath":"feature/srs/08-subscription-billing/3-9-2-make-payment-sepay/spec.md"}'),i={name:"feature/srs/08-subscription-billing/3-9-2-make-payment-sepay/spec.md"};function d(c,e,r,s,l,g){return o(),a("div",null,[...e[0]||(e[0]=[n('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-9-2-—-make-payment-sepay" tabindex="-1">FR 3.9.2 — Make Payment (SePay) <a class="header-anchor" href="#fr-3-9-2-—-make-payment-sepay" aria-label="Permalink to &quot;FR 3.9.2 — Make Payment (SePay)&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.9.2</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-123</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Make Payment (SePay)</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Subscription &amp; Billing (<code>3.9</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20, BR-63, BR-64</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01, MSG02, MSG03, MSG07, MSG51, MSG52</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified (Consolidates <code>subscription-payment-dialog</code>, <code>subscription-auto-checkout</code>, <code>subscription-webhook-corrections</code>, <code>payment-qr-countdown</code>)</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Execute dynamic <strong>SePay (VietQR)</strong> bank-transfer checkout and webhook-driven ACID fulfillment for Agency subscription upgrades/renewals, AI credit top-ups, and S3 storage add-ons. Opening checkout as <code>Owner</code> automatically creates or resumes an idempotent <code>15-minute</code> payment order in an accessible dialog (<code>AgencyPaymentPanel.tsx</code>) with a live <code>mm:ss</code> server-anchored countdown, while <code>POST /api/v1/billing/webhooks/sepay</code> reconciles incoming transfers idempotently and activates entitlements.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized <code>Owner</code>, I want to execute <strong>Make Payment (SePay)</strong> with strong ACID financial/administrative guarantees, deterministic concurrency protection, and complete audit logging so that BrandHub&#39;s operations strictly satisfy <code>BR-20, BR-63, BR-64</code> without manual database intervention.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Canonical Role &amp; Tenant Security:</strong> Server-side authorization enforces <code>Owner</code> on every request (<code>Admin</code> verified against live DB <code>user_system_roles</code>; <code>Owner</code>/<code>Manager</code>/<code>Creator</code> verified against live <code>agencies</code> / <code>workspace_members</code>). Unauthorized callers receive <code>403 FORBIDDEN</code> (<code>MSG07</code>) or scoped <code>404 NOT_FOUND</code> on IDOR probes.</li><li><strong>Core Domain &amp; Financial Invariants:</strong></li></ol><ul><li><strong>1. Auto-Checkout Dialog &amp; <code>15-Minute</code> Countdown (<code>subscription-payment-dialog</code>, <code>subscription-auto-checkout</code>, <code>payment-qr-countdown</code>):</strong> Clicking Upgrade opens an accessible dialog without page reload, using a <code>sessionStorage</code> <code>Idempotency-Key</code> scoped to <code>(userId, agencyId, planCode, periodMonths)</code> and a StrictMode request guard. <code>AgencyPaymentPanel</code> renders a live <code>mm:ss</code> countdown derived from server <code>expiresAt</code> (<code>now + 15 minutes</code>); closing/reopening preserves the deadline, stops background polling while closed, and hides the QR at <code>00:00</code> with an explicit &#39;Create New Order&#39; action.</li><li><strong>2. Webhook Idempotency &amp; Conflict Evidence (<code>subscription-webhook-corrections</code>):</strong> Reserves unique <code>(provider, merchant_account, event_key)</code> in <code>billing_payment_events</code> before parsing transfer content. Exact duplicate event IDs with matching canonical business fingerprint (normalized numeric scale &amp; timestamp offset, or legacy hash) are safe <code>200 {success: true}</code> no-ops; mutated duplicate payloads record immutable conflict audit hashes without overwriting original financial state.</li><li><strong>3. Late-Arrival &amp; Double-Payment Safety (<code>AB-10</code>):</strong> Verified incoming transfers (<code>transferType = in</code>, exact <code>amount</code>, <code>createdAt &lt;= paidAt &lt; expiresAt</code>) fulfill both <code>PENDING_PAYMENT</code> and race-timed <code>EXPIRED</code> orders atomically (updating <code>billing_orders</code>, <code>billing_payments</code>, <code>billing_order_fulfillments</code>, <code>agency_subscriptions</code>, <code>credit_grants</code>, and <code>billing_outbox_events</code> under Agency -&gt; Order row lock order). A second distinct bank transfer on an already <code>FULFILLED</code> order is recorded for <code>MANUAL_REVIEW</code> while strictly preserving <code>SUCCEEDED</code> on the original attempt and never double-granting.</li></ul><ol start="3"><li><strong>Auditability &amp; Idempotency:</strong> Every mutation records correlation <code>requestId</code> and structured audit evidence (<code>audit_logs</code> / <code>billing_audit_events</code> / <code>admin_account_operations</code>), and supports safe retry without duplicate financial side effects.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> All headings, table columns, status pills, dialogs, validation hints, and error banners use key-parallel translations (<code>subscription.checkout.{generatingQr,countdown,expired,createNewOrder,fulfilled}</code> in <code>src/i18n/locales/{vi,en}/subscription.json</code>) on <code>brandhub-web</code> and <code>tr()</code> on <code>brandhub-mobile-app</code> — zero hardcoded Vietnamese or English text in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All components (<code>components/AgencyPaymentPanel.tsx</code>, <code>pages/agency/components/CompanyPlanSelector.tsx</code>, <code>/agency/:agencyId/subscription/checkout</code> on Web and <code>src/screens/billing/SubscriptionPlansScreen.tsx</code>, <code>src/components/billing/BillingModals.tsx</code> (<code>react-native-qrcode-svg</code> VietQR display + countdown) on Mobile) use semantic CSS variables / Tailwind <code>dark:</code> variants and <code>useAppPreferences().palette</code> tokens with WCAG AA contrast across Light and Dark modes.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>components/AgencyPaymentPanel.tsx</code>, <code>pages/agency/components/CompanyPlanSelector.tsx</code>, <code>/agency/:agencyId/subscription/checkout</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/billing/SubscriptionPlansScreen.tsx</code>, <code>src/components/billing/BillingModals.tsx</code> (<code>react-native-qrcode-svg</code> VietQR display + countdown)</li><li><strong>UI States:</strong><ul><li><strong>Loading / Busy:</strong> Skeleton placeholders on initial query; disabled submit button + spinner during in-flight mutation to prevent double-submit races.</li><li><strong>Empty:</strong> Contextual localized empty state (e.g. zero invoices/moderation items/users matching filter) with zero fabricated mock data.</li><li><strong>Success:</strong> Scoped <code>TanStack Query</code> cache invalidation, updated KPI/row state, and localized confirmation toast.</li><li><strong>Conflict / Error:</strong> Explicit <code>409</code> stale-revision reload prompt or localized validation banner preserving user draft inputs.</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method &amp; Endpoint</th><th style="text-align:left;">Auth / Guard</th><th style="text-align:left;">Controller &amp; Service Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST /api/v1/billing/agencies/{agencyId}/orders</code></td><td style="text-align:left;">Bearer (<code>Owner</code>) + <code>Idempotency-Key</code></td><td style="text-align:left;"><code>BillingController.createAgencyOrder()</code> -&gt; auto-creates/resumes <code>PENDING_PAYMENT</code> order (<code>expires_at = created_at + 15m</code>) + VietQR payload</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/billing/agencies/{agencyId}/orders/{orderId}</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>BillingController</code> -&gt; polls authoritative order status (<code>PENDING_PAYMENT</code>, <code>FULFILLED</code>, <code>EXPIRED</code>, <code>MANUAL_REVIEW</code>)</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/billing/webhooks/sepay</code></td><td style="text-align:left;">SePay Webhook <code>Authorization</code> Header</td><td style="text-align:left;"><code>BillingController.sepayWebhook()</code> -&gt; routes to <code>StorageAddonService.acceptIfStorage()</code> or <code>AgencyBillingService.acceptWebhook()</code></td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>FORBIDDEN</code> (<code>403</code>, <code>MSG07</code>): Caller lacks <code>Owner</code> permission or attempts cross-Agency/cross-Workspace access.</li><li><code>CONFLICT</code> (<code>409</code>, <code>MSG03</code>): Stale <code>expectedRevision</code> / <code>rowVersion</code>, duplicate idempotency key with mutated payload, or prohibited self-sanction/last-Admin demotion.</li><li><code>BAD_REQUEST</code> / <code>PAYLOAD_TOO_LARGE</code> (<code>400</code> / <code>413</code>, <code>MSG02</code> / <code>MSG14</code>): Invalid date range, negative/unsafe integer amount, malformed CSV, or de-scoped operation (e.g., plan downgrade or non-SePay provider).</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Related SRS FRs &amp; Modules:</strong> <a href="./../3-9-1-upgrade-plan/spec.html">FR 3.9.1 — Upgrade Plan</a> · <a href="./../3-9-3-view-invoice-history/spec.html">FR 3.9.3 — View Invoice History</a> · <a href="./../../../modules/07-billing-publisher-and-observability/payment-java-runner/spec.html"><code>payment-java-runner</code></a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/08-subscription-billing.html">BA Specification</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Verified via JUnit 5 + isolated PostgreSQL/MongoDB integration tests, TypeScript/Playwright Web checks, Jest Mobile tests, <code>vi.json</code>/<code>en.json</code> key parity, and Light/Dark theme audit (<a href="./test.html">test.md</a>).</li><li><strong>Out of Scope:</strong> De-scoped capabilities (subscription plan downgrade, PayOS/VNPay/Stripe gateways, or copyright/plagiarism moderation).</li></ul>',21)])])}const m=t(i,[["render",d]]);export{u as __pageData,m as default};
